function Assert-PropertyNames($v,[string[]]$e,[string]$p){Assert-True($null -ne $v)"$p is null";$a=@($v.PSObject.Properties.Name|Sort-Object);$x=@($e|Sort-Object);Assert-Equal($a -join "`n")($x -join "`n")"$p property set differs"}
function Get-Sha256([string]$p){$h=[Security.Cryptography.SHA256]::Create();$s=$null;try{$s=[IO.File]::OpenRead($p);return([BitConverter]::ToString($h.ComputeHash($s))).Replace('-','')}finally{if($null -ne $s){$s.Dispose()};$h.Dispose()}}
function Assert-FixtureInfo([string]$path,[string]$name){$info=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json;Assert-PropertyNames $info @('author','dependencies','factorio_version','name','title','version') "fixture info $path";Assert-Equal $info.name $name "fixture info name $path";Assert-Equal $info.version $FixtureVersion "fixture info version $path";Assert-Equal $info.factorio_version $TargetContract.factorio_line "fixture info Factorio line $path";$base=@($info.dependencies|Where-Object{([string]$_) -match ('^base >= '+[regex]::Escape([string]$TargetContract.factorio_line)+'[.]')});Assert-Equal $base.Count 1 "fixture info base dependency $path"}
function Get-ZipEntry([string]$a,[string]$suffix){$z=[IO.Compression.ZipFile]::OpenRead($a);try{$m=@($z.Entries|Where-Object{$_.FullName.EndsWith($suffix,[StringComparison]::Ordinal)});Assert-Equal $m.Count 1 "archive member count for $suffix";return $m[0].FullName}finally{$z.Dispose()}}
function Get-ZipEntrySha256([string]$a,[string]$n){$z=[IO.Compression.ZipFile]::OpenRead($a);$h=[Security.Cryptography.SHA256]::Create();$s=$null;try{$e=$z.GetEntry($n);Assert-True($null -ne $e)"missing archive entry $n";$s=$e.Open();return([BitConverter]::ToString($h.ComputeHash($s))).Replace('-','')}finally{if($null -ne $s){$s.Dispose()};$h.Dispose();$z.Dispose()}}
function Get-ZipEntryText([string]$a,[string]$n){$z=[IO.Compression.ZipFile]::OpenRead($a);$r=$null;try{$e=$z.GetEntry($n);Assert-True($null -ne $e)"missing archive entry $n";$r=[IO.StreamReader]::new($e.Open());return $r.ReadToEnd()}finally{if($null -ne $r){$r.Dispose()};$z.Dispose()}}
function Normalize-ZipMember([string]$n){$x=$n.Replace('\','/').Trim();Assert-True($x.Length -gt 0)'candidate has an empty archive member name';Assert-True(-not $x.StartsWith('/'))"candidate has absolute archive member: $n";$p=@($x.Split('/',[StringSplitOptions]::RemoveEmptyEntries));Assert-True($p.Count -gt 0)"candidate has empty normalized archive member: $n";foreach($q in $p){Assert-True($q -ne '.' -and $q -ne '..')"candidate has traversal archive member: $n"};return($p -join '/')}
function Test-Candidate([string]$a,[string]$hostPath,[string]$locale,[string]$readmePath){
 Assert-Equal ([IO.Path]::GetFileName($a)) ($ExpectedPackageRoot+'.zip') 'candidate filename';$packageInfo=Get-ZipEntryText $a ($ExpectedPackageRoot+'/info.json')|ConvertFrom-Json;Assert-Equal $packageInfo.name 'more-infinite-research' 'candidate mod name';Assert-Equal $packageInfo.version $ExpectedDistributionVersion 'candidate distribution version';Assert-Equal $packageInfo.factorio_version $TargetContract.factorio_line 'candidate Factorio line'
 Assert-True(Test-Path -LiteralPath $a -PathType Leaf)"candidate archive is absent: $a";$he=Get-ZipEntry $a '/prototypes/mir/runtime/research_browser.lua';$le=Get-ZipEntry $a '/locale/en/more-infinite-research.cfg';$re=Get-ZipEntry $a '/README.md';$normalizedHost=Normalize-ZipMember $he;$normalizedLocale=Normalize-ZipMember $le;$normalizedReadme=Normalize-ZipMember $re;Assert-True($normalizedReadme -cmatch '^[^/]+/README[.]md$')"candidate governed README is not a root member: $normalizedReadme";$hh=Get-ZipEntrySha256 $a $he;$lh=Get-ZipEntrySha256 $a $le;$rh=Get-ZipEntrySha256 $a $re;Assert-Equal $hh(Get-Sha256 $hostPath)'candidate browser host bytes differ from current source';Assert-Equal $lh(Get-Sha256 $locale)'candidate en locale bytes differ from current source';Assert-Equal $rh $ExpectedReadmeSha256 "candidate $Target README differs from expected governed hash";$ht=Get-ZipEntryText $a $he;$lt=Get-ZipEntryText $a $le
 foreach($s in @('local function set_hidden(v, force, values)','local function toggle_hidden(v, force, technology)','if options.hidden ~= nil and set_hidden(v, player.force, options.hidden) then','toggle_hidden(v, player.force, tags.technology)','type(index) ~= "number"','index > core.catalogue_limit','type(technology) ~= "string"','type(name) == "string"','button(parent, "toggle-hide"','type = "list-box", name = PREFIX .. "research_entries"','elseif action == "show-hidden"','type(options.page) == "number"','requested_page then v.page = requested_page elseif reset_page then v.page = 1 end')){Assert-True $ht.Contains($s)"host source sentinel missing: $s"};Assert-True($lt -match '(?m)^hide=Hide from my view\r?$')'en locale hide key differs';Assert-True($lt -match '(?m)^show=Show in my view\r?$')'en locale show key differs';Assert-True($lt -match '(?m)^show-hidden=Show all hidden technologies\r?$')'en locale show-hidden key differs'
 $z=[IO.Compression.ZipFile]::OpenRead($a);try{$ms=[Collections.Generic.List[string]]::new();$roots=[Collections.Generic.List[string]]::new();foreach($e in $z.Entries){$m=Normalize-ZipMember $e.FullName;$ms.Add($m)|Out-Null;if(-not $e.FullName.EndsWith('/',[StringComparison]::Ordinal)){$parts=@($m.Split('/'));Assert-True($parts.Count -ge 2)"candidate non-directory member has no package root: $m";$roots.Add($parts[0])|Out-Null};$isGovernedReadme=($m -ceq $normalizedReadme);Assert-True($isGovernedReadme -or ($m -notmatch '(^|/)(fixtures|tests|\.mir|\.codex|\.github|build|dist|docs|scripts|tools)(/|$)|(^|/)(AGENTS\.md|README\.md)$'))"candidate includes excluded repository-only member: $m"};Assert-True($ms.Count -gt 0)'candidate has no archive members';$uniqueRoots=@($roots|Sort-Object -Unique);Assert-Equal $uniqueRoots.Count 1 'candidate package-root count';Assert-Equal $uniqueRoots[0] $ExpectedPackageRoot 'candidate package root';$rootPrefix=$ExpectedPackageRoot+'/';Assert-True($normalizedReadme.StartsWith($rootPrefix,[StringComparison]::Ordinal))'candidate governed README is outside exact package root';Assert-True($normalizedHost.StartsWith($rootPrefix,[StringComparison]::Ordinal))'candidate browser host is outside exact package root';Assert-True($normalizedLocale.StartsWith($rootPrefix,[StringComparison]::Ordinal))'candidate en locale is outside exact package root';return [pscustomobject]@{archive_sha256=Get-Sha256 $a;package_root=$uniqueRoots[0];normalized_members=@($ms|Sort-Object -Unique);host_entry=$he;locale_entry=$le;readme_entry=$re;entry_hashes=[ordered]@{research_browser_lua=$hh;en_locale_cfg=$lh;readme_md=$rh}}}finally{$z.Dispose()}
}
function Write-Utf8NoBom([string]$p,[string]$t){[IO.Directory]::CreateDirectory((Split-Path -Parent $p))|Out-Null;[IO.File]::WriteAllText($p,$t,[Text.UTF8Encoding]::new($false))};function Write-Json([string]$p,$v){Write-Utf8NoBom $p($v|ConvertTo-Json -Depth 32)}
function New-FixtureArchive([string]$s,[string]$n,[string]$v,[string]$b,[string]$info,[string[]]$i){$d=Join-Path $b("$n`_$v");[IO.Directory]::CreateDirectory($d)|Out-Null;Assert-True(Test-Path -LiteralPath $info -PathType Leaf)"fixture info input missing: $info";Copy-Item -LiteralPath $info -Destination (Join-Path $d 'info.json') -Force;foreach($q in $i){$p=Join-Path $s $q;Assert-True(Test-Path -LiteralPath $p)"fixture archive input missing: $p";Copy-Item -LiteralPath $p -Destination $d -Recurse -Force};$a=Join-Path $b("$n`_$v.zip");Compress-Archive -LiteralPath $d -DestinationPath $a -CompressionLevel Optimal;return $a}
