 $a=Start-Owned $stage 'client-a' 1 (@('--config',$aConfig)+$common);$b=Start-Owned $stage 'client-b' 2 (@('--config',$bConfig)+$common)
 return [pscustomobject]@{server=$server;client_a=$a;client_b=$b;server_log=$sl;client_a_log=$al;client_b_log=$bl}
}
function Assert-FixtureNames($v,[string]$p){Assert-PropertyNames $v @('finite','infinite','queued')$p;Assert-Equal $v.finite 'mir-browser-personal-finite'"$p finite technology";Assert-Equal $v.infinite 'mir-browser-personal-infinite'"$p infinite technology";Assert-Equal $v.queued 'mir-browser-personal-infinite'"$p queued technology"}
function Assert-View($v,[string]$p,$mode,$visible,$key,$base){Assert-PropertyNames $v @('force_index','index','mode_selected_index','research_list_selected_index','selected_subject_visible','target_toggle_caption_key','username') $p;Assert-True($v.index -is [int] -or $v.index -is [long])"$p index is not numeric";Assert-True($v.force_index -is [int] -or $v.force_index -is [long])"$p force index is not numeric";Assert-True($v.username -is [string] -and $v.username.Length -gt 0)"$p username is absent";Assert-True($v.research_list_selected_index -is [int] -or $v.research_list_selected_index -is [long])"$p research list selection is not numeric";Assert-True($v.target_toggle_caption_key -is [string])"$p target toggle caption is not a string";if($null -ne $mode){Assert-Equal $v.mode_selected_index $mode "$p mode"};if($null -ne $visible){Assert-Equal $v.selected_subject_visible $visible "$p selected subject visibility"};if($null -ne $key){Assert-Equal $v.target_toggle_caption_key $key "$p target toggle LocalisedString key"};if($null -ne $base){Assert-Equal $v.index $base.index "$p player index changed";Assert-Equal $v.username $base.username "$p service username changed";Assert-Equal $v.force_index $base.force_index "$p force changed"}}
function Assert-FixtureForce($v,[string]$p){Assert-PropertyNames $v @('current_research','research_progress','research_queue','technologies')$p;Assert-Equal $v.current_research 'mir-browser-personal-infinite'"$p current research";Assert-True(($v.research_progress -is [double]) -and [double]::IsFinite([double]$v.research_progress) -and [Math]::Abs(([double]$v.research_progress)-0.42) -le 1e-15) "$p research progress differs";Assert-True($v.research_queue -is [array])"$p queue is not an array";Assert-Equal $v.research_queue.Count 1 "$p queue count";Assert-Equal $v.research_queue[0] 'mir-browser-personal-infinite'"$p queue technology";Assert-PropertyNames $v.technologies @('mir-browser-personal-finite','mir-browser-personal-infinite')"$p technologies";foreach($n in @('mir-browser-personal-finite','mir-browser-personal-infinite')){Assert-PropertyNames $v.technologies.PSObject.Properties[$n].Value @('enabled','level','researched','saved_progress','visible_when_disabled')"$p technologies.$n"}}
function ConvertTo-CanonicalJson($v){if($null -eq $v){return 'null'};if($v -is [string]){return($v|ConvertTo-Json -Compress)};if($v -is [bool]){return $(if($v){'true'}else{'false'})};if($v -is [byte] -or $v -is [int16] -or $v -is [int] -or $v -is [int64] -or $v -is [single] -or $v -is [double] -or $v -is [decimal]){return [Convert]::ToString($v,[Globalization.CultureInfo]::InvariantCulture)};if($v -is [Collections.IEnumerable]){$x=foreach($i in $v){ConvertTo-CanonicalJson $i};return '['+($x -join ',')+']'};$p=@($v.PSObject.Properties);if($p.Count -gt 0){$x=foreach($q in @($p|Sort-Object Name)){(($q.Name|ConvertTo-Json -Compress)+':'+(ConvertTo-CanonicalJson $q.Value))};return '{'+($x -join ',')+'}'};Fail "cannot canonically encode type $($v.GetType().FullName)"}
function Assert-CommonResult($r,[string]$stage,[string[]]$extra,[string]$invariant,$a,$b,$views){$n=@('fixture_force','fixture_technology_names','player_a','player_b','same_force','schema','stage',$invariant)+$extra;Assert-PropertyNames $r $n "result $stage";Assert-Equal $r.schema 1 "result $stage schema";Assert-Equal $r.stage $stage 'result stage';Assert-FixtureNames $r.fixture_technology_names "result $stage fixture names";Assert-Equal $r.same_force $true "result $stage same force";Assert-Equal $r.PSObject.Properties[$invariant].Value $true "result $stage fixture force/queue invariant";Assert-FixtureForce $r.fixture_force "result $stage fixture force";if($views){Assert-View $r.player_a "result $stage player A" 1 $false '<absent>' $a;Assert-View $r.player_b "result $stage player B" 3 $true 'mir-browser.hide' $b}}
function Assert-InitialResult($r){Assert-CommonResult $r 'initial' @('active_full_force_snapshot_unchanged','malformed_hidden','valid_replacement_show_roundtrip') 'fixture_owned_force_queue_unchanged' $null $null $true;Assert-Equal $r.active_full_force_snapshot_unchanged $true 'initial full active-force snapshot invariant';Assert-Equal $r.valid_replacement_show_roundtrip $true 'initial valid replacement/show roundtrip';Assert-PropertyNames $r.malformed_hidden @('duplicate_rejected_without_mutation','sparse_rejected_without_mutation','unknown_rejected_without_mutation') 'initial malformed hidden';foreach($n in $r.malformed_hidden.PSObject.Properties.Name){Assert-Equal $r.malformed_hidden.PSObject.Properties[$n].Value $true "initial malformed hidden $n"};Assert-True($r.player_a.index -ne $r.player_b.index) 'players share an index';Assert-True($r.player_a.username -cne $r.player_b.username) 'client identities are not distinct';Assert-Equal $r.player_a.force_index $r.player_b.force_index 'players do not share a force';return [pscustomobject]@{a=$r.player_a;b=$r.player_b;fixture_force_canonical=ConvertTo-CanonicalJson $r.fixture_force}}
function Assert-ScriptedFixtureInput($r){Assert-PropertyNames $r @('active_full_force_snapshot_unchanged','available_research','fixture_force','fixture_owned_force_queue_unchanged','fixture_technology_names','input_disposition','input_mode','player_a','player_b','same_force','schema','stage') 'scripted fixture input';Assert-Equal $r.schema 1 'scripted fixture input schema';Assert-Equal $r.stage 'scripted-input' 'scripted fixture input stage';Assert-Equal $r.input_mode 'scripted-fixture' 'scripted fixture input mode';Assert-Equal $r.input_disposition 'scripted-fixture-remote-open-only-no-native-mouse-or-keyboard-claim' 'scripted fixture input disposition';Assert-Equal $r.available_research 'mir-browser-personal-finite' 'scripted fixture input preserved available research authority';Assert-Equal $r.same_force $true 'scripted fixture input same force';Assert-Equal $r.fixture_owned_force_queue_unchanged $true 'scripted fixture input fixture force/queue invariant';Assert-Equal $r.active_full_force_snapshot_unchanged $true 'scripted fixture input full active-force invariant';Assert-FixtureNames $r.fixture_technology_names 'scripted fixture input technology names';Assert-FixtureForce $r.fixture_force 'scripted fixture input force';Assert-True($r.player_a.index -ne $r.player_b.index) 'scripted fixture input players share an index';Assert-True($r.player_a.username -cne $r.player_b.username) 'scripted fixture input client identities are not distinct';Assert-Equal $r.player_a.force_index $r.player_b.force_index 'scripted fixture input players do not share a force'}
function Assert-PersistentResult($r,[string]$stage,$base){Assert-CommonResult $r $stage @('active_full_force_snapshot_unchanged')'fixture_owned_force_queue_unchanged' $base.a $base.b $true;Assert-Equal $r.active_full_force_snapshot_unchanged $true "$stage full active-force snapshot invariant";Assert-Equal(ConvertTo-CanonicalJson $r.fixture_force)$base.fixture_force_canonical "$stage fixture force changed"}
function Assert-RemovalResult($r,$base){Assert-CommonResult $r 'removal' @('browser_interface_present','personal_state_readability','removal_disposition') 'fixture_owned_force_queue_unchanged_during_removal' $null $null $false;Assert-Equal $r.browser_interface_present $false 'removal browser interface disposition';Assert-Equal $r.personal_state_readability 'unavailable-removed-owner-no-interface' 'removal readability disposition';Assert-Equal $r.removal_disposition 'before-after-recorded-no-arbitrary-rollback-claim' 'removal rollback disposition';foreach($role in @('a','b')){$view=$r.PSObject.Properties["player_$role"].Value;$baselineView=$base.PSObject.Properties[$role].Value;Assert-PropertyNames $view @('force_index','frame_still_present','index','username') "removal player $role";Assert-Equal $view.index $baselineView.index "removal player $role index";Assert-Equal $view.username $baselineView.username "removal player $role username";Assert-Equal $view.force_index $baselineView.force_index "removal player $role force";Assert-True($view.frame_still_present -is [bool]) "removal player $role frame disposition is not boolean"};Assert-Equal(ConvertTo-CanonicalJson $r.fixture_force) $base.fixture_force_canonical 'removal canonical fixture force differs from initial'}
function Assert-ReaddResult($r,$base){Assert-CommonResult $r 'readd' @('browser_interface_present','personal_state_disposition') 'fixture_owned_force_queue_unchanged_during_removal' $null $null $false;Assert-Equal $r.browser_interface_present $true 'readd browser interface disposition';Assert-Equal $r.personal_state_disposition 'observed-after-owner-readd-not-arbitrary-rollback-claim' 'readd rollback disposition';Assert-View $r.player_a 'readd player A' $null $null $null $base.a;Assert-View $r.player_b 'readd player B' $null $null $null $base.b;Assert-True(@('<absent>','mir-browser.show','mir-browser.hide') -contains $r.player_a.target_toggle_caption_key) 'readd player A target toggle key is not an observed browser key';Assert-True(@('<absent>','mir-browser.show','mir-browser.hide') -contains $r.player_b.target_toggle_caption_key) 'readd player B target toggle key is not an observed browser key';Assert-Equal(ConvertTo-CanonicalJson $r.fixture_force) $base.fixture_force_canonical 'readd canonical fixture force differs from initial'}
function Get-RepositorySnapshot([string]$r){return [ordered]@{commit=(& git -C $r rev-parse HEAD).Trim();tree=(& git -C $r rev-parse 'HEAD^{tree}').Trim();status_porcelain=@(& git -C $r status --porcelain=v1)}}
function Assert-Dossier($Dossier) {
  Assert-PropertyNames $Dossier @('boundaries', 'explicit_non_claims', 'fixture_technologies', 'gui_structure', 'player_outcome', 'results', 'schema', 'scope', 'target') 'dossier'
  Assert-Equal $Dossier.schema 1 'dossier schema'
  Assert-Equal $Dossier.scope $TargetContract.dossier_scope 'dossier scope'
  Assert-PropertyNames $Dossier.target @('engine_selection', 'factorio_line', 'network_scope') 'dossier target'
  Assert-Equal $Dossier.target.factorio_line $TargetContract.factorio_line 'dossier Factorio line'
  Assert-Equal $Dossier.target.engine_selection $TargetContract.engine_selection 'dossier engine selection'
  Assert-Equal $Dossier.target.network_scope 'two exact localhost client processes connected to one loopback dedicated server' 'dossier network scope'
  Assert-FixtureNames $Dossier.fixture_technologies 'dossier fixture technologies'
  Assert-PropertyNames $Dossier.gui_structure @('frame_name', 'mode', 'research_list', 'selected_subject') 'dossier GUI structure'
  Assert-Equal $Dossier.gui_structure.frame_name $BrowserRoot 'dossier GUI root'
  Assert-Equal $Dossier.gui_structure.research_list 'tags.mir_browser=research-list on the native list-box; selected_index is the rendered selected-subject indicator' 'dossier research list binding'
  Assert-Equal $Dossier.gui_structure.selected_subject 'tags.mir_browser=toggle-hide and tags.technology=<technology> proves that selected technology is rendered in native detail' 'dossier selected subject binding'
  Assert-Equal $Dossier.gui_structure.mode 'tags.mir_browser=mode on native drop-down' 'dossier mode binding'
  Assert-PropertyNames $Dossier.player_outcome @('player_a', 'player_b', 'queue', 'same_force') 'dossier player outcome'
  Assert-Equal $Dossier.player_outcome.same_force $true 'dossier same force'
  Assert-PropertyNames $Dossier.player_outcome.player_a @('hidden', 'mode_selected_index', 'selected_subject_visible', 'target_toggle_caption_key') 'dossier player A outcome'
  Assert-PropertyNames $Dossier.player_outcome.player_b @('hidden', 'mode_selected_index', 'selected_subject_visible', 'target_toggle_caption_key') 'dossier player B outcome'
  Assert-Equal $Dossier.player_outcome.player_a.mode_selected_index 1 'dossier player A mode'
  Assert-Equal $Dossier.player_outcome.player_a.selected_subject_visible $false 'dossier player A selected subject visibility'
  Assert-Equal $Dossier.player_outcome.player_a.target_toggle_caption_key '<absent>' 'dossier player A target toggle key'
  Assert-Equal ($Dossier.player_outcome.player_a.hidden -join "`n") 'mir-browser-personal-infinite' 'dossier player A hidden'
  Assert-Equal $Dossier.player_outcome.player_b.mode_selected_index 3 'dossier player B mode'
  Assert-Equal $Dossier.player_outcome.player_b.selected_subject_visible $true 'dossier player B selected subject visibility'
  Assert-Equal $Dossier.player_outcome.player_b.target_toggle_caption_key 'mir-browser.hide' 'dossier player B target toggle key'
  Assert-Equal @($Dossier.player_outcome.player_b.hidden).Count 0 'dossier player B hidden'
  Assert-Equal $Dossier.player_outcome.queue 'The hidden technology remains queued on the shared force.' 'dossier queue meaning'
  Assert-PropertyNames $Dossier.boundaries @('active_force_snapshot', 'configuration_change', 'mod_readd', 'mod_removal', 'personal_view', 'save_reload') 'dossier boundaries'
  Assert-Equal $Dossier.boundaries.personal_view 'The fixture observes per-player selected-subject visibility through the native research list and target detail tag; sparse, duplicate and unknown hidden payloads must leave that view unchanged, without claiming physical mouse or keyboard input.' 'dossier personal view boundary'
  Assert-Equal $Dossier.boundaries.save_reload 'The saved per-player views and the full active force snapshot are re-observed after a real server save/reload and two reconnects.' 'dossier save/reload boundary'
  Assert-Equal $Dossier.boundaries.configuration_change 'Adding one exact inert local configuration marker triggers Factorio configuration change; the saved per-player views and full active force snapshot are re-observed.' 'dossier configuration boundary'
  Assert-Equal $Dossier.boundaries.mod_removal 'Literal MIR removal records owner interface, GUI presence and fixture-owned force/queue before/after disposition; it never claims that removed-mod GUI/storage is readable or rollback-capable.' 'dossier removal boundary'
  Assert-Equal $Dossier.boundaries.mod_readd 'MIR re-addition opens a selected fixture technology and records observed native presentation only; it does not assert arbitrary restoration of removed-owner personal state.' 'dossier readd boundary'
  Assert-Equal $Dossier.boundaries.active_force_snapshot 'All active force technologies exactly compare enabled, researched, level, visible_when_disabled and saved_progress, plus current research, progress and queue while MIR is active; literal MIR removal/re-add compares only fixture-owned technology/current/progress/queue facts because MIR-owned prototypes legitimately change.' 'dossier force boundary'
  Assert-PropertyNames $Dossier.results @('active_full_force_snapshot_unchanged', 'fixture_owned_force_queue_unchanged', 'fixture_owned_force_queue_unchanged_during_removal', 'malformed_hidden_rejection', 'personal_state_disposition', 'personal_state_readability', 'removal_disposition', 'selected_subject_visibility') 'dossier results'
  Assert-Equal $Dossier.results.malformed_hidden_rejection 'Sparse, duplicate and unknown hidden payloads leave the prior selected-subject visibility and target detail caption unchanged.' 'dossier malformed hidden result meaning'
  Assert-Equal $Dossier.results.selected_subject_visibility 'The target is hidden for player A and visibly selected for player B through the native research list/detail contract; clearing player A then restoring its hidden input round-trips only player A.' 'dossier selected subject result meaning'
  Assert-Equal $Dossier.results.active_full_force_snapshot_unchanged 'True only for initial, save-reload and inert configuration-change phases after exact all-technology comparison.' 'dossier active result meaning'
  Assert-Equal $Dossier.results.fixture_owned_force_queue_unchanged 'True only for MIR-active phases after exact fixture-owned technology/current/progress/queue comparison.' 'dossier active fixture result meaning'
  Assert-Equal $Dossier.results.fixture_owned_force_queue_unchanged_during_removal 'True only for literal MIR-removal and re-add phases after exact fixture-owned comparison; it is not a full active force snapshot claim.' 'dossier removal fixture result meaning'
  Assert-Equal $Dossier.results.personal_state_readability 'unavailable-removed-owner-no-interface' 'dossier readability result meaning'
  Assert-Equal $Dossier.results.removal_disposition 'before-after-recorded-no-arbitrary-rollback-claim' 'dossier removal result meaning'
  Assert-Equal $Dossier.results.personal_state_disposition 'observed-after-owner-readd-not-arbitrary-rollback-claim' 'dossier readd result meaning'
  $nonClaims = @($TargetContract.non_claims)
  Assert-Equal (@($Dossier.explicit_non_claims) -join "`n") ($nonClaims -join "`n") 'dossier explicit nonclaims'
}
function Invoke-CreateSave([string]$save,[string]$config,[string]$mods){$i=Start-Owned 'create' 'save-create' 3 @('--create',$save,'--config',$config,'--mod-directory',$mods,'--console-log',(Join-Path $RunRoot 'create-current.log'),'--no-log-rotation','--disable-audio');$end=[DateTime]::UtcNow.AddSeconds($TimeoutSeconds);while(-not $i.process.HasExited -and [DateTime]::UtcNow -lt $end){Start-Sleep -Milliseconds 250};if(-not $i.process.HasExited){$i.process.Kill($true);$i.process.WaitForExit(15000)|Out-Null;Fail 'save creation timed out'};$i.exit_code=$i.process.ExitCode;$i.exit_disposition='completed';$i.process.Dispose();$i.disposed=$true;Assert-Equal $i.exit_code 0 'initial save creation exit code';Assert-True(Test-Path -LiteralPath $save -PathType Leaf)'initial save was not created';$null=Assert-MIRLibraryLoadedSelection -Activation $profile.activation -LogPath (Join-Path $RunRoot 'create-current.log')}
function Invoke-ProofStage([string]$stage,[string]$save,[string]$result,$next,[int]$port,[string]$sc,[string]$ac,[string]$bc,[string]$mods,[string]$serverData,[string]$clientAData,[string]$clientBData){
 $d=Join-Path $RunRoot(Join-Path 'stages' $stage);[IO.Directory]::CreateDirectory($d)|Out-Null
 Write-Json(Join-Path $d 'server-settings.json')([ordered]@{name="MIR browser personal-state $stage";description='';tags=@();max_players=2;visibility=[ordered]@{public=$false;lan=$false};username='';password='';token='';game_password='';require_user_verification=$false;max_upload_in_kilobytes_per_second=0;max_upload_slots=5;minimum_latency_in_ticks=0;ignore_player_limit_for_returning_players=$false;allow_commands='admins-only';autosave_interval=0;autosave_slots=1;afk_autokick_interval=0;auto_pause=$false;only_admins_can_pause_the_game=$false})
 $rp=Join-Path $serverData(Join-Path 'script-output'(Join-Path 'browser-personal-state'"$result.json"));if(Test-Path -LiteralPath $rp -PathType Leaf){Remove-Item -LiteralPath $rp -Force};if($null -ne $next -and(Test-Path -LiteralPath $next -PathType Leaf)){Remove-Item -LiteralPath $next -Force}
 $x=Start-Stage $stage $save $port $sc $ac $bc $mods $serverData $clientAData $clientBData $d;$i=@($x.client_a,$x.client_b,$x.server);$native=$null;$scripted=$null
 if($stage -eq 'initial'){if($InputMode -ceq 'Native'){$readyPath=Join-Path $serverData 'script-output/browser-personal-state/native-input-ready.json';if(Test-Path -LiteralPath $readyPath){Remove-Item -LiteralPath $readyPath -Force};$ready=Wait-NativeInputReady $readyPath $i;$native=[ordered]@{ready=$ready;actions=@(Invoke-NativeBrowserInput $x.client_a $ready.player_a.geometry 'native-input-player-a';Invoke-NativeBrowserInput $x.client_b $ready.player_b.geometry 'native-input-player-b')};$nativeResultPath=Join-Path $serverData 'script-output/browser-personal-state/native-input.json';$native.result=Wait-Result $nativeResultPath $i;$nativeA=$native.result.native_input.texts.PSObject.Properties[[string]$ready.player_a.index].Value;$nativeB=$native.result.native_input.texts.PSObject.Properties[[string]$ready.player_b.index].Value;Assert-Equal $native.result.available_research 'mir-browser-personal-finite' 'native browser input preserved available research authority';Assert-Equal $nativeA.text 'native-input-player-a' 'native player A keyboard text';Assert-Equal $nativeB.text 'native-input-player-b' 'native player B keyboard text'}else{$scriptedPath=Join-Path $serverData 'script-output/browser-personal-state/scripted-input.json';if(Test-Path -LiteralPath $scriptedPath){Remove-Item -LiteralPath $scriptedPath -Force};$scripted=Wait-Result $scriptedPath $i;Assert-ScriptedFixtureInput $scripted}}
 $r=Wait-Result $rp $i;$o=(Get-LogText $x.server_log).Length;if($null -ne $next){Wait-SuccessorSave $next $x.server_log $o $i};Stop-Owned $stage;foreach($log in @($x.server_log,$x.client_a_log,$x.client_b_log)){$null=Assert-MIRLibraryLoadedSelection -Activation $profile.activation -LogPath $log};$copy=Join-Path $d "server-$stage.log";Copy-Item -LiteralPath $x.server_log -Destination $copy -Force
 return [pscustomobject]@{stage=$stage;result=$r;native_input=$native;scripted_fixture_input=$scripted;result_sha256=Get-Sha256 $rp;fixture_force_canonical=ConvertTo-CanonicalJson $r.fixture_force;server_log=$copy;server_log_sha256=Get-Sha256 $copy;client_a_log_sha256=Get-Sha256 $x.client_a_log;client_b_log_sha256=Get-Sha256 $x.client_b_log;input_save=$save;input_save_sha256=Get-Sha256 $save;successor_save=$next;successor_save_sha256=if($null -eq $next){$null}else{Get-Sha256 $next}}
}
